CREATE VIEW restaurant_whatsapp_registry AS SELECT id, (CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(data) THEN data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'')) IN (10,11) THEN '55' || replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(data) THEN data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'') ELSE replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(data) THEN data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'') END) AS phone FROM restaurants;
