CREATE TRIGGER restaurant_whatsapp_insert BEFORE INSERT ON restaurants WHEN (CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'')) IN (10,11) THEN '55' || replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'') ELSE replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'') END) <> '' BEGIN SELECT RAISE(ABORT,'whatsapp_already_registered') WHERE EXISTS(SELECT 1 FROM restaurant_whatsapp_registry WHERE phone = (CASE WHEN length(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'')) IN (10,11) THEN '55' || replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'') ELSE replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.whatsapp'),''),' ',''),'+',''),'(',''),')',''),'-',''),'.',''),char(9),''),char(10),''),char(13),''),char(160),'') END) AND id <> NEW.id); END;
